import base64,hashlib,json,os,stat,sys
from pathlib import Path
root=Path("/data/yanruj/EvolveSWDB_runs/probata-resume-20261016-t28-native86-cold-context-v1")
assert not os.path.lexists(root), "fresh cold context already exists"
rows=json.loads(base64.b64decode(""))
assert len(rows)==5 and sum(r["bytes"] for r in rows)<131072
root.mkdir(mode=0o700)
result=[]
for row in rows:
 assert Path(row["name"]).name==row["name"]
 data=base64.b64decode(row["base64"],validate=True)
 assert len(data)==row["bytes"] and hashlib.sha256(data).hexdigest()==row["sha256"]
 p=root/row["name"]
 with p.open("xb") as stream: stream.write(data)
 assert stat.S_ISREG(p.lstat().st_mode) and p.resolve()==p
 assert hashlib.sha256(p.read_bytes()).hexdigest()==row["sha256"]
 result.append({"path":str(p),"bytes":row["bytes"],"sha256":row["sha256"]})
assert {p.name for p in root.iterdir()}=={r["name"] for r in rows}
print(json.dumps({"status":"STAGED_CONTEXT_ONLY_READER_NOT_EXECUTED","files":result},sort_keys=True))
